 CAST(NULL AS STRING) campaign_name,CAST(NULL AS STRING) adset_name,CAST(NULL AS STRING) ad_name,TIMESTAMP('2000-01-01') _dataform_updated_at FROM UNNEST([1]) WHERE FALSE),
 joined as (
  select
    events.* except (_dataform_updated_at),
    touchpoints.touchpoint_id,
    touchpoints.session_id,
    touchpoints.session_start_timestamp,
    touchpoints.first_page_host as landing_page_host,
    touchpoints.first_page_path as landing_page_path,
    coalesce(touchpoints.utm_source, touchpoints.channel_source, 'offline') as source,
    coalesce(touchpoints.utm_medium, touchpoints.channel_medium, 'offline') as medium,
    touchpoints.utm_campaign,
    touchpoints.utm_content,
    touchpoints.utm_term,
    touchpoints.campaign_id,
    touchpoints.adset_id,
    touchpoints.ad_id,
    coalesce(ad_names.campaign_name, touchpoints.utm_campaign, 'unknown') as campaign_name,
    coalesce(ad_names.adset_name, 'unknown') as adset_name,
    coalesce(ad_names.ad_name, 'unknown') as ad_name,
    greatest(
      events._dataform_updated_at,
      coalesce(touchpoints._dataform_updated_at, timestamp('1970-01-01')),
      coalesce(ad_names._dataform_updated_at, timestamp('1970-01-01'))
    ) as _dataform_updated_at
  from conversion_events events
  left join touchpoints touchpoints
    on touchpoints.profile_id = events.profile_id
   and touchpoints.touchpoint_time <= events.conversion_time
  left join ad_names
    on ad_names.source = touchpoints.utm_source
   and ad_names.campaign_id is not distinct from touchpoints.campaign_id
   and ad_names.adset_id is not distinct from touchpoints.adset_id
   and ad_names.ad_id is not distinct from touchpoints.ad_id
),

classified as (
  select
    *,
    lower(source) = 'direct'
      and lower(medium) = 'none' as is_direct_touch,
    lower(source) in ('google', 'meta')
      and lower(medium) in ('cpc', 'paid', 'paid_social')
      and campaign_id is not null
      and ad_id is not null as is_paid_ad_touch
  from joined
),

ordered as (
  select
    *,
    count(*) over (partition by conversion_id) as total_touchpoints,
    row_number() over (
      partition by conversion_id
      order by coalesce(session_start_timestamp, conversion_time), touchpoint_id
    ) as touchpoint_number
  from classified
),

eligible as (
  select
    *,
    is_direct_touch and touchpoint_number > 1 as is_excluded_direct_touch
  from ordered
),

ranked as (
  select
    *,
    countif(not is_direct_touch) over (
      partition by conversion_id
    ) as non_direct_touchpoints,
    countif(not is_direct_touch) over (
      partition by conversion_id
      order by coalesce(session_start_timestamp, conversion_time), touchpoint_id
      rows between unbounded preceding and current row
    ) as non_direct_touchpoint_number,
    countif(not is_excluded_direct_touch) over (
      partition by conversion_id
    ) as attribution_touchpoints,
    countif(not is_excluded_direct_touch) over (
      partition by conversion_id
      order by coalesce(session_start_timestamp, conversion_time), touchpoint_id
      rows between unbounded preceding and current row
    ) as attribution_touchpoint_number,
    countif(is_direct_touch and touchpoint_number = 1) over (
      partition by conversion_id
    ) > 0 as first_touch_is_direct,
    countif(is_excluded_direct_touch) over (
      partition by conversion_id
    ) as excluded_direct_touchpoints,
    countif(is_paid_ad_touch) over (
      partition by conversion_id
    ) as paid_ad_touchpoints,
    countif(is_paid_ad_touch) over (
      partition by conversion_id
      order by coalesce(session_start_timestamp, conversion_time), touchpoint_id
      rows between unbounded preceding and current row
    ) as paid_ad_touchpoint_number
  from eligible
),

weighted as (
  select
    *,
    case
      when first_touch_is_direct then 'first_touch_direct'
      when excluded_direct_touchpoints > 0 then 'later_direct_return'
      else 'no_direct'
    end as journey_direct_status,
    case
      when is_excluded_direct_touch then 0.0
      when attribution_touchpoints = 1 then 1.0
      when attribution_touchpoints = 2 then 0.5
      when attribution_touchpoint_number = 1 then 0.4
      when attribution_touchpoint_number = attribution_touchpoints then 0.4
      else 0.2 / (attribution_touchpoints - 2)
    end as multi_touch_weight,
    if(
      not is_excluded_direct_touch and attribution_touchpoint_number = 1,
      1.0,
      0.0
    ) as first_touch_weight,
    if(
      not is_excluded_direct_touch
        and attribution_touchpoint_number = attribution_touchpoints,
      1.0,
      0.0
    ) as last_touch_weight
  from ranked
)
,
 labeled AS (SELECT *,TO_JSON_STRING([CAST(DATE(COALESCE(session_start_timestamp,conversion_time),'America/Los_Angeles') AS STRING),
